export const METRICS=['rhr','hrv','sleep','steps','activity','mood'];
export const median=a=>{const s=a.filter(Number.isFinite).sort((a,b)=>a-b);return s.length?(s[Math.floor((s.length-1)/2)]+s[Math.ceil((s.length-1)/2)])/2:null};
export const clamp=(n,a=0,b=1)=>Math.min(b,Math.max(a,n));
export function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T00:00:00Z'))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;}
export function calendar(year){const days=[];for(let t=Date.UTC(year,0,1);new Date(t).getUTCFullYear()===year;t+=86400000)days.push({date:new Date(t).toISOString().slice(0,10)});return days;}
export function demoData(year=2025){let seed=73;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};return calendar(year).map((d,i)=>{const season=Math.sin(i/365*Math.PI*2),ill=i>74&&i<84?1:0,trip=i>201&&i<222?1:0;return {...d,rhr:Math.round(59-season*2+rand()*5+ill*9),hrv:Math.round(43+season*9+rand()*18-ill*22),sleep:+(6.5+rand()*2+season*.3-ill*.7).toFixed(2),steps:Math.round(3500+rand()*7500+trip*6500-ill*3000),activity:Math.round(rand()*60+trip*30),mood:clamp(Math.round(3+season*.6+rand()*2-ill*2),1,5)}})}
export function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c;}if(quoted)throw Error('An opening quote has no closing quote. Check the CSV file.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw Error('The file needs a header and at least one data row.');const headers=rows.shift().map((v,i)=>v.replace(/^\uFEFF/,'').trim()||`Column ${i+1}`);if(new Set(headers).size!==headers.length)throw Error('Column names must be unique.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`CSV row ${i+2} has ${r.length} fields; expected ${headers.length}.`);return Object.fromEntries(headers.map((h,j)=>[h,r[j]]))});}
export function normalize(rows,map){const seen=new Set();let skipped=0;const days=[];for(const row of rows){const date=String(row[map.date]??'').trim();if(!validDate(date)){skipped++;continue}if(seen.has(date))throw Error(`More than one row for ${date}. Import daily summaries with one row per date.`);seen.add(date);const d={date};for(const k of METRICS){const v=row[map[k]];if(v===null||v===undefined||String(v).trim()==='')continue;const n=Number(v);const bounds={rhr:[20,250],hrv:[.01,1000],sleep:[0,24],steps:[0,200000],activity:[0,1440],mood:[1,5]}[k];if(!Number.isFinite(n)||n<bounds[0]||n>bounds[1])throw Error(`${k} on ${date} is outside the supported range (${bounds.join('–')}). Check units or leave the field unmapped.`);d[k]=n;}days.push(d)}if(!days.some(d=>METRICS.some(k=>Number.isFinite(d[k]))))throw Error('No usable measurements found. Check dates (YYYY-MM-DD) and field mappings.');return {days:days.sort((a,b)=>a.date.localeCompare(b.date)),skipped};}
const aliases={date:['date','day'],rhr:['rhr','resting_heart_rate','restingheartrate','resting heart rate'],hrv:['hrv','hrv_ms','sdnn','rmssd'],sleep:['sleep','sleep_hours','sleephours','sleep hours'],steps:['steps','step_count'],activity:['activity','active_minutes','exercise_minutes'],mood:['mood','mood_rating']};
export function suggest(headers){return Object.fromEntries(Object.entries(aliases).map(([k,a])=>[k,headers.find(h=>a.includes(h.toLowerCase()))||'']));}
export function sonify(days,settings){const annual={};for(const k of METRICS)annual[k]=days.map(d=>d[k]).filter(Number.isFinite);return days.map((d,i)=>{const value=k=>Number.isFinite(d[k])?d[k]:null;const ref=k=>{if(settings.interpretation==='baseline'){const a=days.slice(Math.max(0,i-28),i).map(d=>d[k]).filter(Number.isFinite);return a.length>=7?median(a):null}return median(annual[k])};const relative=k=>{const v=value(k),b=ref(k);if(v===null||b===null)return null;const scale=k==='rhr'?Math.max(3,b*.06):Math.max(5,b*.2);return (v-b)/scale};const sleep=value('sleep')===null?null:clamp(d.sleep/settings.target);const hr=relative('rhr'),hv=relative('hrv');const colors={mood:value('mood')===null?null:(d.mood-1)/4,hrv:hv===null?null:clamp(.5+hv*.2,0,.85),sleep};let color=colors[settings.melody];if(color!==null)color=clamp(.5+(color-.5)*settings.sensitivity,0,settings.melody==='hrv'?.85:1);const activity=value(settings.rhythm);const values=annual[settings.rhythm];const sorted=values.slice().sort((a,b)=>a-b);const max=sorted[Math.floor((sorted.length-1)*.9)]||1;const movement=activity===null?null:clamp(activity/Math.max(max,1)*settings.sensitivity);const tensions={rhr:hr===null?null:clamp(hr*.3*settings.sensitivity),hrv:hv===null?null:clamp(-hv*.3*settings.sensitivity),sleep:sleep===null?null:1-sleep,none:0};return {...d,color,movement,tension:tensions[settings.tension],fullness:sleep,hasData:METRICS.some(k=>Number.isFinite(d[k]))}})}
export async function parseApple(file,onProgress=()=>{}){const reader=file.stream().getReader(),decoder=new TextDecoder();let tail='',count=0;const buckets=new Map();const types={HKQuantityTypeIdentifierRestingHeartRate:'rhr',HKQuantityTypeIdentifierHeartRateVariabilitySDNN:'hrv',HKQuantityTypeIdentifierStepCount:'steps',HKQuantityTypeIdentifierAppleExerciseTime:'activity',HKCategoryTypeIdentifierSleepAnalysis:'sleep'};const decode=s=>s.replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>');while(true){const {done,value}=await reader.read();tail+=done?decoder.decode():decoder.decode(value,{stream:true});const re=/<Record\b[^>]*>/g;let m,last=0;while((m=re.exec(tail))){last=re.lastIndex;const a={};for(const v of m[0].matchAll(/([\w]+)="([^"]*)"/g))a[v[1]]=decode(v[2]);const k=types[a.type];if(!k)continue;const source=a.sourceName||'Unknown';const key=k+'|'+source;if(!buckets.has(key))buckets.set(key,{k,source,records:[]});const date=(k==='sleep'?a.endDate:a.startDate)?.slice(0,10);if(!validDate(date))continue;if(k==='sleep'){if(!/Asleep/.test(a.value)&&a.value!=='1')continue;const start=Date.parse(a.startDate),end=Date.parse(a.endDate);if(Number.isFinite(start)&&end>start)buckets.get(key).records.push({date,start,end});}else{let n=Number(a.value);if(k==='hrv'&&(a.unit==='s'||a.unit==='sec'))n*=1000;if(Number.isFinite(n))buckets.get(key).records.push({date,n});}count++;}tail=tail.slice(last);if(tail.length>2000000){const start=tail.lastIndexOf('<Record');tail=start>=0?tail.slice(start):tail.slice(-1000)}if(done)break;onProgress(count);await new Promise(r=>setTimeout(r,0));}const selected=[],daily=new Map();for(const k of METRICS){const b=[...buckets.values()].filter(b=>b.k===k).sort((a,b)=>b.records.length-a.records.length)[0];if(!b||!b.records.length)continue;selected.push(`${k}: ${b.source}`);const grouped=new Map();for(const r of b.records){if(!grouped.has(r.date))grouped.set(r.date,[]);grouped.get(r.date).push(r)}for(const [date,rs]of grouped){if(!daily.has(date))daily.set(date,{date});let n;if(k==='sleep'){const intervals=rs.sort((a,b)=>a.start-b.start);let total=0,start=intervals[0].start,end=intervals[0].end;for(const v of intervals.slice(1)){if(v.start<=end)end=Math.max(end,v.end);else{total+=end-start;start=v.start;end=v.end}}n=(total+end-start)/3600000}else n=['steps','activity'].includes(k)?rs.reduce((s,r)=>s+r.n,0):median(rs.map(r=>r.n));daily.get(date)[k]=n;}}return {rows:[...daily.values()],sources:selected};}
